  const SurahInfo({
    required this.id,
    required this.nameArabic,
    required this.nameEnglish,
    required this.nameTransliteration,
    required this.ayahCount,
    required this.revelationType,
  });

  bool get isMakki => revelationType.toLowerCase() == 'makki';
}

